  'plans.faqWhatIsPlus': 'Chatyy One គឺអ្វី?',
  'plans.faqWhatIsPlusAnswer': 'វាជាផែនការប្រមូលផ្តុំរបស់ Chatyy ដែលការពារសារទាំងអស់របស់អ្នក, រូបថត និងវីដេអូ។ ជាមួយ Chatyy One, ទោះបីអ្នកលុបអ្វីមួយដោយគ្មានចេតនា, អ្នកអាចស្ដារឡើងវិញក្នុងរយៈពេល 30 ថ្ងៃ។ លើសពីនេះ, អ្នកទទួលបាន 200GB នៃការផ្ទុក, One AI ជាជំនួយកម្រិតផ្ទាល់, និងអាចផ្ញើឯកសារដល់ 100MB។',
