  'plans.faqHowFamily': 'ផែនការ Pro ធ្វើការយ៉ាងដូចម្តេច?',
  'plans.faqHowFamilyAnswer': 'អ្នកអាចបន្ថែមមនុស្ស 4 នាក់ពីគ្រួសាររបស់អ្នក។ មនុស្សទាំងអស់ចែករំលែក 500GB នៃការផ្ទុក និងទទួលបានអត្ថប្រយោជន៍ទាំងអស់ពី Chatyy One។ មនុស្សរៀងរាល់គ្នាមានកន្លែងឯកជនរបស់ខ្លួន — មិនមាននរណាម្នាក់ឃើញឯកសាររបស់អ្នកផ្សេងទៀត។',
  'plans.faqChangePlanAnswer': 'បាទ! ប្រសិនបើអ��នកធ្វើបច្ចុប្បន្នភាពពី Plus ទៅ Pro, តែត្រូវគិតតម្លៃខុសគ្នា។ ប្រសិនបើធ្វើបច្ចុប្បន្នភាពតិច, ផែនការបច្ចុប្បន្ននៅតែសកម្មរហូតដល់ចុងបញ្ចប់រយៈពេល។',
